create or replace function public.app_admin_criar_recorrencia(p_token text,p_descricao text,p_categoria text,p_fornecedor text,p_valor numeric,p_periodicidade text,p_proximo_vencimento date) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; v_id uuid; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.perfil not in('admin','administrador','gestor') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; insert into public.financeiro_recorrencias(empresa_id,descricao,categoria,fornecedor,valor,periodicidade,proximo_vencimento,created_by) values(v.empresa_id,trim(p_descricao),trim(p_categoria),nullif(trim(p_fornecedor),''),p_valor,p_periodicidade,p_proximo_vencimento,v.usuario_id) returning id into v_id; return jsonb_build_object('sucesso',true,'id',v_id); end; $$;
create or replace function public.app_admin_criar_parcelamento(p_token text,p_tipo text,p_credor text,p_descricao text,p_valor_entrada numeric,p_quantidade integer,p_valor_padrao numeric,p_primeiro_vencimento date,p_valores jsonb default '[]'::jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; s_id uuid; i integer; v_valor numeric; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.perfil not in('admin','administrador','gestor') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; if p_quantidade<1 or p_quantidade>120 then return jsonb_build_object('sucesso',false,'erro','A quantidade deve estar entre 1 e 120 parcelas'); end if; insert into public.financeiro_parcelamentos(empresa_id,tipo,credor,descricao,valor_entrada,quantidade_parcelas,valor_padrao,data_primeiro_vencimento,created_by) values(v.empresa_id,p_tipo,trim(p_credor),trim(p_descricao),coalesce(p_valor_entrada,0),p_quantidade,p_valor_padrao,p_primeiro_vencimento,v.usuario_id) returning id into s_id; for i in 1..p_quantidade loop v_valor:=coalesce(nullif((p_valores->>(i-1)),'')::numeric,p_valor_padrao); insert into public.financeiro_parcelas(empresa_id,parcelamento_id,numero,valor,vencimento) values(v.empresa_id,s_id,i,v_valor,(p_primeiro_vencimento+(i-1)*interval '1 month')::date); end loop; return jsonb_build_object('sucesso',true,'id',s_id); end; $$;
grant execute on function public.app_admin_criar_recorrencia(text,text,text,text,numeric,text,date) to anon,authenticated;
grant execute on function public.app_admin_criar_parcelamento(text,text,text,text,numeric,integer,numeric,date,jsonb) to anon,authenticated;
